function coordinates(latitude:string,longitude:string){return {latitude:decimal(latitude,'Latitud',-90,90),longitude:decimal(longitude,'Longitud',-180,180)}}
function navigationUrl(latitude:number,longitude:number){return `https://www.google.com/maps/dir/?api=1&destination=${latitude},${longitude}&travelmode=driving`}
